pages=json.loads((R/'build/sword-ui-v28/research/sword-pages.json').read_text())
groups={5:'Yoru',6:'Gryphon',7:'Shodai Kitetsu',8:'Wado Ichimonji',9:'Sandai Kitetsu',10:'Yubashiri',11:'Shusui',12:'Shigure',14:'Kiribachi',15:'Terry Sword',16:'Eisen Whip',17:'Funkfreed',18:'Soul Solid',19:'Oto|Kogarashi',20:'Warabide',21:'Raiu',22:'Kaken',23:'Kikoku',24:'Durandal',25:'Same-kiri',26:'Pretzel',27:'Shirauo',28:'Napoleon',29:'Nidai Kitetsu',30:'Nagirito|Kashu|Burn Blade|Men-Kiri Doku|Franken',31:'Kirisame|Henry Blazer|Karakuri|Desert Espada|Ice Saber',32:'Amano Murakumo|Blue Sword|Espada Girl|Shichiseiken',33:'Ryuma original katana|Cyrano broadsword|Buggy knives|Mihawk knife|Hatchan blades|Bogard katana|Dalton sword',34:'Pell sword|Chaka sword|Noland katana|T-Bone sword|Helmeppo kukris|Moria scissors-blades|X Drake saber|Killer blades',35:'Rayleigh sword|Momonga katana|Strawberry swords|John Giant katana|Atmos swords|Fossa katana|Haruta saber|Little Oars Jr sword|Squard sword',36:'Hyouzou swords|Kinemon katanas|Suleiman sword|Kyros sword|Rebecca sword|Diamante rapier|Pica katana|Jack shotels',37:'Inuarashi rapier|Smoothie sword|Kiku katana|Shutenmaru katana|King katana|Kyoushiro katana|Oden early katana illustration|Hitetsu katana',38:'Higuma cutlass|Cabaji cutlass|Buggy cutlass|Hyota sword|Arrow sword|Sarquiss kukris|Pickles swords|Peepley Lulu katanas|Jigoro sabers|Doberman katana',39:'Onigumo sabers|Comil katanas|Yamakaji katana|Lacroix saber|Stainless katana|Delacuaji cutlass|McGuy electric sword|Doma cutlasses|Karma sabers|Ramba rapier|Blenheim saber|Albion large knife|Lip Doughty sword',40:'Brownbeard sword|Yarisugi sword|Jeet sabers|Dagama katanas|Gion katana|Wanda rapier|Sicilian rapier|Bobbin sword|Streusen sword|Charlotte Raisin katana|Charlotte Snack sword|Orochi katana|Hihimaru katana'}
