for page,names in groups.items():
 for name in names.split('|'):rows.append({'number':len(rows)+1,'design':name,'sheetIndex':page,'sourceImage':pages[page]})
rows=rows[:100];assert len(rows)==100
out=R/'docs/art/swords-menu-army-v28';out.mkdir(parents=True,exist_ok=True)
(out/'references.json').write_text(json.dumps({'scope':'100件刀剑设计；来自One Piece动画/漫画系列的爱好者图鉴，不是100部不同动漫，也不声称全为动画帧或官方图。参考图只在本地build研究目录，不进入游戏资产。配色和像素表现以Minecraft为准。','source':'https://thelibraryofohara.com/op-sword-encyclopedia/','inspection':'已逐张查看42页组成的9张联系表；按设计去重，成对同型兵器计1件。','swords':rows,'menus':json.loads((R/'build/sword-ui-v28/research/menu-sources.json').read_text()),'methods':{'imperial_soldier':'直刃、脊线、克制护手，制式兵器','royal_guard':'微弯轮廓、护手端部识别，保留佩刀身份','rebel_soldier':'局部缺锋，非全表面随机战损','assassin':'细短刃与低反差刀背，限制装饰','bandit_thug':'宽刀腹与厚刀背，刃口集中亮部','zuwu_daoshou':'环首和简洁单刃','ludun_jiashi':'盾侧阔剑与简洁横护手','tiesuo_chihou':'短锋和局部钩背，控制外扩','kuijun_sishi':'短军匕、简洁柄尾和缠握层次'}},ensure_ascii=False,indent=2))
print('100 design records saved')
